import{_ as s,o as a,c as n,a8 as i}from"./chunks/framework.CAT8sTE0.js";const c=JSON.parse('{"title":"HTTP 与网络基础","description":"","frontmatter":{},"headers":[],"relativePath":"service/common/http-network-basics.md","filePath":"service/common/http-network-basics.md"}'),e={name:"service/common/http-network-basics.md"};function l(o,t,d,p,r,h){return a(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="http-与网络基础" tabindex="-1">HTTP 与网络基础 <a class="header-anchor" href="#http-与网络基础" aria-label="Permalink to &quot;HTTP 与网络基础&quot;">​</a></h1><blockquote><p><strong>优先级：P0（后端上岗必备）</strong> — &quot;输入 URL 回车后发生什么&quot;是前端转后端面试的第一题，也是理解连接池、Nginx、Netty 的地基。</p></blockquote><div class="tip custom-block"><p class="custom-block-title">背景</p><p>前端天天发请求，但请求出了浏览器之后发生了什么，通常是知识盲区。本文按&quot;一次请求的完整旅程&quot;组织：DNS → TCP → TLS → HTTP → 响应，每一步都回答&quot;后端为什么要关心它&quot;。</p></div><h2 id="全景-一次请求的完整旅程" tabindex="-1">全景：一次请求的完整旅程 <a class="header-anchor" href="#全景-一次请求的完整旅程" aria-label="Permalink to &quot;全景：一次请求的完整旅程&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant B as 浏览器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant D as DNS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as 服务器(Nginx)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant A as 应用(Tomcat)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant DB as 数据库</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B-&gt;&gt;D: www.example.com 的 IP？</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D--&gt;&gt;B: 1.2.3.4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B-&gt;&gt;S: TCP 三次握手</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S--&gt;&gt;B: 连接建立</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B-&gt;&gt;S: TLS 握手（HTTPS）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S--&gt;&gt;B: 证书校验通过</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B-&gt;&gt;S: GET /api/order HTTP/1.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;A: 反向代理转发</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A-&gt;&gt;DB: SQL 查询</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DB--&gt;&gt;A: 结果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A--&gt;&gt;S: HTTP 响应</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S--&gt;&gt;B: 200 + JSON</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over B,S: keep-alive：连接复用，后续请求不再握手</span></span></code></pre></div><p>面试答这道题的结构：<strong>DNS 解析 → TCP 握手 →（HTTPS 则 TLS 握手）→ 发 HTTP 请求 → 服务器处理（Nginx → 应用 → 数据库）→ 响应渲染</strong>。每一层能展开一层，就是深度。</p><h2 id="一、http-协议层" tabindex="-1">一、HTTP 协议层 <a class="header-anchor" href="#一、http-协议层" aria-label="Permalink to &quot;一、HTTP 协议层&quot;">​</a></h2><h3 id="请求与响应的结构" tabindex="-1">请求与响应的结构 <a class="header-anchor" href="#请求与响应的结构" aria-label="Permalink to &quot;请求与响应的结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求行:  GET /api/orders?page=1 HTTP/1.1</span></span>
<span class="line"><span>请求头:  Host: api.example.com</span></span>
<span class="line"><span>         Cookie: token=xxx</span></span>
<span class="line"><span>         Content-Type: application/json</span></span>
<span class="line"><span>空行</span></span>
<span class="line"><span>请求体:  {&quot;name&quot;: &quot;...&quot;}          # GET 没有，POST/PUT 有</span></span>
<span class="line"><span></span></span>
<span class="line"><span>响应行:  HTTP/1.1 200 OK</span></span>
<span class="line"><span>响应头:  Content-Type: application/json</span></span>
<span class="line"><span>         Cache-Control: max-age=60</span></span>
<span class="line"><span>空行</span></span>
<span class="line"><span>响应体:  {&quot;data&quot;: [...]}</span></span></code></pre></div><h3 id="http-1-1-keep-alive-连接复用" tabindex="-1">HTTP/1.1 keep-alive：连接复用 <a class="header-anchor" href="#http-1-1-keep-alive-连接复用" aria-label="Permalink to &quot;HTTP/1.1 keep-alive：连接复用&quot;">​</a></h3><p><strong>默认开启</strong>（HTTP/1.0 要显式 <code>Connection: keep-alive</code>）。一次 TCP 连接可以传多个请求响应，省掉反复握手的开销。</p><ul><li><strong>前端视角</strong>：浏览器对同一域名默认保持 6~8 个 TCP 连接，<code>fetch</code> 发起的请求在底层被复用</li><li><strong>后端视角</strong>：这是<strong>连接池存在的原因</strong>——握手成本高（见 <a href="#二tcp可靠传输的基石">TCP 三次握手</a>，连接必须复用</li></ul><h3 id="http-2-多路复用" tabindex="-1">HTTP/2：多路复用 <a class="header-anchor" href="#http-2-多路复用" aria-label="Permalink to &quot;HTTP/2：多路复用&quot;">​</a></h3><p>HTTP/1.1 的队头阻塞：同一连接上请求必须排队。HTTP/2 用<strong>二进制分帧 + 多路复用</strong>，一个连接上并行多个请求，互相不阻塞。</p><table tabindex="0"><thead><tr><th></th><th>HTTP/1.1</th><th>HTTP/2</th></tr></thead><tbody><tr><td>传输格式</td><td>文本</td><td>二进制帧</td></tr><tr><td>并发</td><td>一连接一请求排队</td><td>一连接多请求并行</td></tr><tr><td>头部压缩</td><td>无</td><td>HPACK（头部差异压缩）</td></tr><tr><td>服务端推送</td><td>无</td><td>支持（已逐渐弃用）</td></tr></tbody></table><p><strong>后端要知道的</strong>：Nginx/Spring Boot 默认支持 h2，配置 <code>listen 443 ssl http2;</code> 即可，业务代码无感。</p><h3 id="缓存头速查-前后端联调高频" tabindex="-1">缓存头速查（前后端联调高频） <a class="header-anchor" href="#缓存头速查-前后端联调高频" aria-label="Permalink to &quot;缓存头速查（前后端联调高频）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>头</th><th>含义</th><th>典型用法</th></tr></thead><tbody><tr><td><code>Cache-Control: max-age=3600</code></td><td>缓存 1 小时，期间不问服务器</td><td>静态资源（JS/CSS/图片）</td></tr><tr><td><code>Cache-Control: no-cache</code></td><td><strong>可以缓存，但每次用前问服务器</strong>（不是&quot;不缓存&quot;）</td><td>HTML 入口、API 数据</td></tr><tr><td><code>Cache-Control: no-store</code></td><td>真正不缓存</td><td>敏感数据（余额、token）</td></tr><tr><td><code>ETag</code> + <code>If-None-Match</code></td><td>资源指纹，没变返回 <strong>304</strong>（不传 body，省流量）</td><td>协商缓存</td></tr><tr><td><code>Last-Modified</code> + <code>If-Modified-Since</code></td><td>按时间协商（精度到秒，ETag 更准）</td><td>同上</td></tr></tbody></table><p><strong>强缓存 vs 协商缓存</strong>：<code>max-age</code> 没过期 → 直接用本地（200 from disk/memory cache）；过期了 → 带 <code>ETag</code> 问服务器，没变 304、变了 200。</p><h3 id="幂等性与安全性-后端设计必知" tabindex="-1">幂等性与安全性（后端设计必知） <a class="header-anchor" href="#幂等性与安全性-后端设计必知" aria-label="Permalink to &quot;幂等性与安全性（后端设计必知）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>幂等</th><th>安全</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td>✅</td><td>✅</td><td>只读，不应有副作用</td></tr><tr><td>POST</td><td>❌</td><td>❌</td><td>创建/提交，重复调用产生多条</td></tr><tr><td>PUT</td><td>✅</td><td>❌</td><td>全量替换，重复调用结果一样</td></tr><tr><td>DELETE</td><td>✅</td><td>❌</td><td>删一次和删多次效果一样</td></tr><tr><td>PATCH</td><td>❌</td><td>❌</td><td>部分修改，<code>{&quot;count&quot;: +1}</code> 不幂等</td></tr></tbody></table><p><strong>后端应用</strong>：重试机制（Feign/Ribbon 自动重试）必须设计成对幂等方法重试，否则重复下单。</p><h2 id="二、tcp-可靠传输的基石" tabindex="-1">二、TCP：可靠传输的基石 <a class="header-anchor" href="#二、tcp-可靠传输的基石" aria-label="Permalink to &quot;二、TCP：可靠传输的基石&quot;">​</a></h2><h3 id="三次握手-必考-会画" tabindex="-1">三次握手（必考，会画） <a class="header-anchor" href="#三次握手-必考-会画" aria-label="Permalink to &quot;三次握手（必考，会画）&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as 客户端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as 服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: SYN（seq=x）我要连接</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S--&gt;&gt;C: SYN（seq=y）+ ACK（x+1）可以，我也要连接</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ACK（y+1）好，连接建立</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: 之后开始传数据</span></span></code></pre></div><p><strong>为什么是三次不是两次</strong>：防止历史失效连接请求。客户端第一个 SYN 在网络里堵了很久突然到达服务端，两次握手会让服务端白建一条连接浪费资源；第三次握手让客户端确认&quot;我连的是当前有效的服务端&quot;。</p><p><strong>前端类比</strong>：类似 WebSocket 建立前的 HTTP Upgrade 往返，只不过 TCP 是更底层的&quot;建立可靠信道&quot;。</p><h3 id="四次挥手-必考" tabindex="-1">四次挥手（必考） <a class="header-anchor" href="#四次挥手-必考" aria-label="Permalink to &quot;四次挥手（必考）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端: FIN（我发完了）→  服务端: ACK</span></span>
<span class="line"><span>服务端: FIN（我也发完了）→ 客户端: ACK + TIME_WAIT 等待 2MSL</span></span></code></pre></div><p>服务端收到 FIN 后可能还有数据要传，所以 ACK 和 FIN 分开发（比握手多一次）。客户端最后要等 <strong>2MSL</strong>（最长报文寿命的两倍）确保服务端收到最后一个 ACK。</p><h3 id="time-wait-线上高频" tabindex="-1">TIME_WAIT（线上高频） <a class="header-anchor" href="#time-wait-线上高频" aria-label="Permalink to &quot;TIME_WAIT（线上高频）&quot;">​</a></h3><p>主动关连接的一方进入 TIME_WAIT（Linux 默认 60s）。<strong>TIME_WAIT 堆积</strong>（几万个）有两个后果：本地端口被占满，新连接建不起来；内核内存吃紧——高并发短连接场景的经典故障。</p><p><strong>先搞清两个前提</strong>，解法才对症：</p><ul><li><strong>为什么等 2MSL</strong>：① 确保最后一个 ACK 到达对端——对端没收到会重发 FIN，这边还没消失才能重传；② 让这条连接&quot;迟到&quot;的旧报文在网络里自然消散，不污染复用同一四元组的新连接</li><li><strong>谁主动关</strong>：HTTP keep-alive 场景下通常是<strong>服务端</strong>先关（keepalive_timeout 到期），所以堆积发生在服务端。Nginx 反代、Java 服务间调用（HttpClient/Feign/OkHttp）不配连接复用时，服务端会堆出一片 TIME_WAIT</li></ul><p><strong>解法（按有效性排序）</strong>：</p><table tabindex="0"><thead><tr><th>解法</th><th>具体做法</th><th>说明</th></tr></thead><tbody><tr><td>① 复用连接（根治）</td><td>Nginx <code>upstream keepalive</code> + <code>proxy_http_version 1.1</code> + <code>proxy_set_header Connection &quot;&quot;</code>；Java 侧 HttpClient/Feign/OkHttp/DB 全走连接池</td><td>连接不频繁新建关闭，TIME_WAIT 根本不会产生。后端服务间调用必配</td></tr><tr><td>② <code>net.ipv4.tcp_tw_reuse=1</code></td><td><code>sysctl net.ipv4.tcp_tw_reuse</code></td><td><strong>只对主动发起连接的一端（客户端）有效</strong>，服务端堆积别指望它——面试常考的坑</td></tr><tr><td>③ <code>net.ipv4.tcp_max_tw_buckets</code></td><td>调大或设上限兜底</td><td>超限后内核丢弃并告警，防止内存耗尽，是&quot;保命&quot;不是&quot;治病&quot;</td></tr><tr><td>④ 扩大临时端口</td><td><code>net.ipv4.ip_local_port_range</code></td><td>端口耗尽时的应急手段，治标</td></tr></tbody></table><p><strong>排查命令</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                            # 各状态连接总数概览</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> state</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> time-wait</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # TIME_WAIT 数量</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ss</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> state</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> close-wait</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # CLOSE_WAIT：对端关了、你还没 close</span></span></code></pre></div><p><strong>必须区分 CLOSE_WAIT</strong>：TIME_WAIT 堆积多半是配置/架构问题（没复用连接）；<strong>CLOSE_WAIT 堆积是代码 bug</strong>——连接被对端关了，你这边还没调 <code>close()</code>，查连接泄漏（排查手法衔接 <a href="/knowledge/service/common/database-connection-pool.html">数据库连接池</a> 的泄漏检测）。</p><ul><li><strong>面试题</strong>：TIME_WAIT 在哪一端？——主动关的一方（keep-alive 场景通常是服务端）；线上堆了几万个怎么解？——优先复用连接治本，<code>tcp_tw_reuse</code> 只救客户端。</li></ul><h3 id="tcp-为什么可靠" tabindex="-1">TCP 为什么可靠 <a class="header-anchor" href="#tcp-为什么可靠" aria-label="Permalink to &quot;TCP 为什么可靠&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>一句话</th></tr></thead><tbody><tr><td>序列号 + 确认应答</td><td>每个字节编号，丢了知道丢哪</td></tr><tr><td>超时重传</td><td>等不到 ACK 就重发</td></tr><tr><td>流量控制</td><td>滑动窗口，接收方说了算发多快</td></tr><tr><td>拥塞控制</td><td>网络说了算：慢启动 → 拥塞避免 → 快重传快恢复</td></tr></tbody></table><p><strong>TCP vs UDP</strong>：TCP 可靠有序有拥塞控制（HTTP/数据库连接都基于它）；UDP 无连接快但不保证送达（视频直播、DNS 查询、游戏）。</p><h2 id="三、dns-域名到-ip" tabindex="-1">三、DNS：域名到 IP <a class="header-anchor" href="#三、dns-域名到-ip" aria-label="Permalink to &quot;三、DNS：域名到 IP&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[浏览器缓存] --&gt;|未命中| B[系统缓存/ hosts]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|未命中| C[本地 DNS 服务器]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|未命中| D[根 DNS]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[顶级域 .com]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[权威 DNS example.com]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F --&gt;|返回 IP| C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt;|返回 IP| A</span></span></code></pre></div><p><strong>查找顺序</strong>：浏览器 DNS 缓存 → 操作系统缓存（hosts 文件）→ 本地域名服务器（LDNS，运营商/公司提供）→ 根 → 顶级域 → 权威域名服务器。<strong>逐级缓存</strong>，所以换域名/IP 后要等 TTL 过期才全网生效。</p><p><strong>后端要知道的</strong>：</p><ul><li><strong>DNS 缓存导致发布不生效</strong>：改了域名解析，用户这边还有旧 IP（等 TTL，或本地 <code>sudo dscacheutil -flushcache</code> 强制刷新，Mac）</li><li><strong>DNS 轮询</strong>：一个域名配多个 A 记录，是最简陋的负载均衡（没有健康检查，挂了也返回）</li><li>排查手段：<code>dig example.com</code> / <code>nslookup example.com</code> 看解析到哪</li></ul><h2 id="四、https-与-tls-握手" tabindex="-1">四、HTTPS 与 TLS 握手 <a class="header-anchor" href="#四、https-与-tls-握手" aria-label="Permalink to &quot;四、HTTPS 与 TLS 握手&quot;">​</a></h2><p>HTTPS = HTTP + TLS。TLS 解决三件事：<strong>加密</strong>（防窃听）、<strong>完整性</strong>（防篡改）、<strong>身份认证</strong>（防冒充，靠证书链）。</p><h3 id="tls-1-2-握手-两次-rtt-面试常考" tabindex="-1">TLS 1.2 握手（两次 RTT，面试常考） <a class="header-anchor" href="#tls-1-2-握手-两次-rtt-面试常考" aria-label="Permalink to &quot;TLS 1.2 握手（两次 RTT，面试常考）&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as 客户端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as 服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ClientHello（支持的 TLS 版本/加密套件/随机数1）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S--&gt;&gt;C: ServerHello（选定套件/随机数2）+ 证书（含公钥）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: 验证证书链：是否可信 CA 签发、域名匹配、未过期</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: 用证书公钥加密&quot;预主密钥&quot;发送</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: 双方用三个随机数算出会话密钥</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: Finished（之后全部用会话密钥对称加密通信）</span></span></code></pre></div><p><strong>三个随机数</strong>：客户端随机 + 服务端随机 + 预主密钥 → 生成对称会话密钥。为什么不用证书公钥直接加密数据：<strong>非对称加密慢</strong>，只用来协商密钥，后续用对称加密（AES）传输。</p><p><strong>TLS 1.3</strong> 简化成 1-RTT，且默认前向安全，Nginx 现在默认启用。</p><h3 id="tls-1-3-握手-1-rtt-现在的主流" tabindex="-1">TLS 1.3 握手（1-RTT，现在的主流） <a class="header-anchor" href="#tls-1-3-握手-1-rtt-现在的主流" aria-label="Permalink to &quot;TLS 1.3 握手（1-RTT，现在的主流）&quot;">​</a></h3><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as 客户端</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as 服务器</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ClientHello（支持的套件 + ECDHE 公钥 + 随机数）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C: 自己生成一对临时密钥，把公钥直接放进第一条消息</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;S: 用自己的私钥 + 客户端公钥，经椭圆曲线 DH 算出共享密钥</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S--&gt;&gt;C: ServerHello（选定套件）+ 加密扩展 + 证书 + Finished</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: 双方各自独立算出同一把会话密钥，之后即传应用数据</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: Finished</span></span></code></pre></div><p><strong>为什么 1.3 能压到 1-RTT（关键在 ECDHE）</strong>：1.2 里客户端必须<strong>等服务端回 ServerHello</strong>（拿到服务端的 ECDHE 参数和公钥）之后才能算密钥、发 Finished，所以握手要两个来回。1.3 把这个依赖砍掉了——客户端在 ClientHello 第一条消息里就带上自己的 <strong>ECDHE 公钥</strong>，服务端收到后立即用椭圆曲线 Diffie-Hellman 算出共享密钥（各自的私钥 + 对方的公钥 → 同一把密钥，公钥可以明文传播），一个来回就够开始传数据。</p><p>ECDHE 的数学直觉：双方各自用私钥和&quot;对方的公钥&quot;做同样的椭圆曲线运算，结果必然相同；而别人只有两个公钥，推不出私钥。算法细节（油漆类比、<code>a·G</code>）见 <a href="/knowledge/browser/https.html">浏览器篇 HTTPS</a>——两篇口径一致，可对照阅读。</p><p><strong>1.2 → 1.3 改了什么</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>TLS 1.2</th><th>TLS 1.3</th></tr></thead><tbody><tr><td>握手 RTT</td><td>2</td><td>1（老客户端重连可 0-RTT）</td></tr><tr><td>密钥交换</td><td>RSA 密钥传输 + ECDHE 并存</td><td>只剩（EC）DHE——默认前向安全</td></tr><tr><td>前向安全</td><td>看套件选没选</td><td>强制</td></tr><tr><td>握手内容</td><td>Finished 之后才加密</td><td>ServerHello 之后的扩展、证书就已经加密</td></tr><tr><td>被砍掉的</td><td>—</td><td>RSA 密钥传输、RC4/3DES/SHA-1、压缩（CRIME 攻击的根源）、重新协商</td></tr></tbody></table><p><strong>前向安全（PFS）</strong>：每次握手独立协商会话密钥。服务端私钥就算泄露，攻击者也解不了<strong>已经录下来的历史流量</strong>——历史流量用的密钥不是私钥直接加密的。这是 1.3 把 RSA 密钥传输砍掉的核心理由。</p><p><strong>0-RTT 是什么</strong>：老客户端重连时带着上次的会话票据，第一个数据包就发应用数据，零握手。代价是<strong>可被重放攻击</strong>（同一请求被重发一次），所以只适合 GET 这类幂等请求——Nginx 的 <code>ssl_early_data on;</code> 默认关闭就是这个原因。</p><h3 id="证书与部署" tabindex="-1">证书与部署 <a class="header-anchor" href="#证书与部署" aria-label="Permalink to &quot;证书与部署&quot;">​</a></h3><ul><li><strong>证书链</strong>：服务器证书 → 中间 CA → 根 CA（浏览器内置）。任何一环不被信任就红色警告</li><li><strong>Let&#39;s Encrypt</strong>：免费证书，90 天有效期，<code>certbot</code> 自动续期</li><li><strong>Nginx 配置</strong>：见 <a href="/knowledge/service/common/nginx-web-container.html">Nginx 与 Web 容器</a> 的 HTTPS 终止</li></ul><h2 id="五、cdn-离用户最近的缓存" tabindex="-1">五、CDN：离用户最近的缓存 <a class="header-anchor" href="#五、cdn-离用户最近的缓存" aria-label="Permalink to &quot;五、CDN：离用户最近的缓存&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U[用户] --&gt;|1. 请求| E[边缘节点 就近]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|2. 未命中| O[源站服务器]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    O --&gt;|3. 回源取| E</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt;|4. 缓存并返回| U</span></span></code></pre></div><p><strong>原理</strong>：把静态资源（JS/CSS/图片/视频）缓存到全国各地的边缘节点，用户就近取，不回源站。</p><p><strong>回源</strong>：边缘没缓存 → 回源站拉 → 缓存 → 返回。源站要被回源流量保护（CDN 厂商的带宽质量比源站高，能挡大部分攻击）。</p><p><strong>刷新/预热</strong>：发布了新版本但 CDN 还是旧文件 → 提交刷新 URL（少量）或预热（大版本前主动推）。</p><p><strong>前端视角</strong>：构建产物文件名带 hash（<code>app.a3f2b.js</code>）是 CDN 友好的根本原因——内容变文件名才变，可以放心配 <code>max-age=31536000</code>（一年）。</p><h2 id="六、-输入-url-发生什么-完整答法" tabindex="-1">六、&quot;输入 URL 发生什么&quot;完整答法 <a class="header-anchor" href="#六、-输入-url-发生什么-完整答法" aria-label="Permalink to &quot;六、&quot;输入 URL 发生什么&quot;完整答法&quot;">​</a></h2><p>按这个顺序讲，每层能展开：</p><ol><li><strong>浏览器</strong>：查缓存（强缓存命中直接渲染，不发请求；未命中才发）→ 拼请求（cookie、UA、Accept 头）</li><li><strong>DNS</strong>：域名解析成 IP（逐级缓存，见上）</li><li><strong>TCP</strong>：三次握手建立连接（复用则跳过）</li><li><strong>TLS</strong>：HTTPS 握手协商密钥（证书校验）</li><li><strong>HTTP</strong>：发送请求，Nginx 反向代理到应用</li><li><strong>服务端</strong>：应用处理（鉴权 → 业务 → DB/Redis/MQ）→ 拼响应（含缓存头）</li><li><strong>浏览器渲染</strong>：HTML → DOM/CSSOM → 渲染树 → 布局绘制 → JS 执行 →（异步请求再走一轮）</li><li><strong>收尾</strong>：TCP 连接 keep-alive 保活，或四次挥手关闭</li></ol><p><strong>加分项</strong>（说一个就够）：HTTP/2 多路复用让第 5 步的多个请求并行；CDN 让静态资源在第 1 步就命中边缘节点。</p><h3 id="缓存分层-静态和动态要分开看" tabindex="-1">缓存分层：静态和动态要分开看 <a class="header-anchor" href="#缓存分层-静态和动态要分开看" aria-label="Permalink to &quot;缓存分层：静态和动态要分开看&quot;">​</a></h3><p>面试答&quot;输入 URL&quot;时，缓存这一段最容易只说一半。<strong>先分内容类型</strong>——不同内容走的链路不一样，缓存策略的&quot;定的人&quot;也不一样：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B[&quot;浏览器&quot;] --&gt;|&quot;① 强缓存命中&quot;| S1[&quot;到此为止&lt;br/&gt;不发请求&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|&quot;未命中/过期&quot;| CDN[&quot;CDN 边缘节点&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CDN --&gt;|&quot;② 命中&quot;| S2[&quot;边缘直接返回&lt;br/&gt;不回源&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CDN --&gt;|&quot;未命中/需重验&quot;| NX[&quot;Nginx&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    NX --&gt;|&quot;③ 命中&quot;| S3[&quot;nginx 直接返回&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    NX --&gt;|&quot;未命中&quot;| APP[&quot;应用（只有动态内容到这里）&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    APP --&gt;|&quot;④ 响应带 Cache-Control / ETag&quot;| NX</span></span></code></pre></div><table tabindex="0"><thead><tr><th>内容</th><th>走到哪</th><th>缓存策略谁定</th></tr></thead><tbody><tr><td><strong>静态资源</strong>（js/css/图片）</td><td>浏览器 → CDN → <strong>nginx 读文件即止</strong>，到不了应用</td><td><strong>nginx 定</strong>（<code>expires</code> / <code>add_header Cache-Control</code>，见 <a href="/knowledge/service/common/nginx-web-container.html">Nginx 篇动静分离</a>）</td></tr><tr><td><strong>HTML 入口</strong></td><td>看项目形态：<strong>SPA 的 index.html 是静态文件</strong>，和 js/css 一样放 nginx root 目录，nginx 直接给（<code>location = /index.html</code> 或 try_files 兜底）；只有 <strong>SSR/模板页</strong>（Thymeleaf 等）才是应用生成</td><td>SPA：<strong>nginx 定</strong>；SSR：应用定</td></tr><tr><td><strong>API 响应</strong></td><td>浏览器 → CDN → nginx <code>proxy_cache</code> → 应用</td><td><strong>应用定</strong>（响应头在 Controller/拦截器里写）</td></tr></tbody></table><p><strong>协商缓存到底能走到哪——分清场景</strong>：</p><ul><li><strong>静态资源和 SPA 的 HTML</strong>：都在 nginx 层闭环。nginx 静态文件默认带 <code>Last-Modified</code> / <code>ETag</code> 响应头，浏览器带 <code>If-None-Match</code> / <code>If-Modified-Since</code> 问回来，nginx 按文件状态直接回 <strong>304</strong>——<strong>请求连 Tomcat 都到不了，更别说应用代码</strong></li><li><strong>API 响应</strong>：缓存头由应用说了算，<code>ETag</code> + <code>If-None-Match</code> 的 304 <strong>可以一路穿透 CDN 和 nginx 的 proxy_cache，问到源站应用</strong>——这才是&quot;协商缓存走到源站&quot;的正确语境</li></ul><p>所以 mall 这种 SPA 项目，<strong>前端侧全部内容（js/css/图片/HTML）的缓存协商都在 nginx 层闭环</strong>，没有一个是走到 Java 应用的；只有 API 响应才可能问到应用。</p><p>再强调一次维度区分：<strong>&quot;缓存命中与否&quot;和&quot;请求能走到哪&quot;是两回事</strong>。静态资源哪怕浏览器、CDN、nginx 层层都没命中，也只是继续往下穿透到 nginx 读文件返回 200，<strong>依然到不了应用</strong>——见 <a href="/knowledge/service/common/nginx-web-container.html">Nginx 篇动静分离</a>列的三种例外（proxy_pass 的 API、文件不存在时的兜底转发、以及让 Spring Boot 自己服务静态资源的反模式）。</p><p><strong>两个关键认知</strong>（面试高频追问）：</p><ul><li><code>Cache-Control: no-cache</code> <strong>不是&quot;不缓存&quot;</strong>——是&quot;每次用之前必须先协商&quot;；<code>no-store</code> 才是真不缓存</li><li>所以经典分工是：带 hash 的前端产物配 <code>max-age=31536000, immutable</code> 走强缓存；HTML 入口配 <code>no-cache</code> 每次都协商——发布新版本时用户立刻能拿到新引用，同时长缓存资源一点不浪费</li></ul><h2 id="面试题速查" tabindex="-1">面试题速查 <a class="header-anchor" href="#面试题速查" aria-label="Permalink to &quot;面试题速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>一句话答案</th></tr></thead><tbody><tr><td>三次握手为什么不是两次</td><td>防止历史失效连接请求让服务端白建连接；第三次确认连接有效</td></tr><tr><td>四次挥手为什么多一次</td><td>服务端收到 FIN 后可能还有数据要发，ACK 和 FIN 分开发</td></tr><tr><td>TIME_WAIT 是什么</td><td>主动关连接一方等待 2MSL，确保对方收到最后 ACK；大量出现在高并发短连接服务端</td></tr><tr><td>HTTP 和 HTTPS 区别</td><td>HTTPS = HTTP + TLS：加密、完整性、身份认证</td></tr><tr><td>强缓存和协商缓存</td><td>max-age 没过期直接用；过期带 ETag 问服务器，304 不传 body</td></tr><tr><td>HTTP/2 改进</td><td>二进制分帧 + 多路复用（一连接并行多请求）+ 头部压缩</td></tr><tr><td>DNS 解析过程</td><td>浏览器缓存 → 系统缓存 → LDNS → 根 → 顶级域 → 权威</td></tr><tr><td>TCP 和 UDP 区别</td><td>TCP 可靠有序有拥塞控制；UDP 快但不保证送达</td></tr><tr><td>为什么 TCP 连接要复用</td><td>握手 1 个 RTT + 系统开销，高并发下不可接受；连接池同理</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/knowledge/service/common/nginx-web-container.html">Nginx 与 Web 容器</a> - 请求旅程的下一站：反向代理与 Tomcat</li><li><a href="/knowledge/service/java/java-io.html">Java IO/NIO 与序列化</a> - TCP 握手在 NIO 多路复用里的位置</li><li><a href="/knowledge/service/java/java-netty.html">Netty 入门</a> - 基于 NIO 的网络编程框架</li><li><a href="/knowledge/service/common/database-connection-pool.html">数据库连接池与数据源</a> - &quot;连接必须复用&quot;的最典型案例</li><li>前端视角对照（同一协议的浏览器侧）：<a href="/knowledge/browser/tcp.html">TCP 通信</a>、<a href="/knowledge/browser/dns.html">DNS 域名解析</a>、<a href="/knowledge/browser/https.html">HTTPS</a>、<a href="/knowledge/browser/storage-cache.html">浏览器缓存</a>、<a href="/knowledge/browser/http-methods.html">HTTP 方法</a></li></ul>`,88)])])}const k=s(e,[["render",l]]);export{c as __pageData,k as default};
